// La anti-repetición general (misma alerta en 10 min) la hace Enviar_Alerta.
// n8n devuelve un ítem vacío cuando la consulta no trae filas: se filtra por una columna clave.
// D3: no hay respaldo exitoso en más de 24 h. El SQL solo devuelve la fila si el evento no se alertó antes.
const r = $input.all().map(i => i.json).find(r => r.marca);
if (!r) return [];
const hace = r.horas == null ? 'nunca se ha respaldado' : `hace ${r.horas} h`;
return [{ json: {
  codigo: 'D3',
  severidad: 'CRÍTICA',
  tipo: 'Sin respaldo en más de 24 horas',
  tabla: 'backups',
  detalle: `${r.marca} (${hace}, umbral: 24 h). Último intento: ${r.ultimo_intento || 'ninguno'} (${r.ultimo_estado || 'N/A'})`,
  query: "SELECT MAX(fecha) FROM backups WHERE estado = 'ok';",
  usuario: 'N/A (proceso de respaldo)',
  accion: 'Ejecutar ./scripts/backup.sh y revisar el cron del servidor y el espacio en disco.'
}}];
